import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.Cv-B11KK.js";const u=JSON.parse('{"title":"bbtex vs TeXShop, LaTeXTools and AUCTeX","description":"","frontmatter":{},"headers":[],"relativePath":"editor-comparison.md","filePath":"editor-comparison.md","lastUpdated":1790322248000}'),a={name:"editor-comparison.md"};function n(s,t,i,c,l,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="bbtex-vs-texshop-latextools-and-auctex" tabindex="-1">bbtex vs TeXShop, LaTeXTools and AUCTeX <a class="header-anchor" href="#bbtex-vs-texshop-latextools-and-auctex" aria-label="Permalink to &quot;bbtex vs TeXShop, LaTeXTools and AUCTeX&quot;">​</a></h1><p>How bbtex in BBEdit compares with the editors people usually mean when they say &quot;a good LaTeX setup&quot;: <a href="https://pages.uoregon.edu/koch/texshop/" target="_blank" rel="noreferrer">TeXShop</a> (the Mac&#39;s own LaTeX editor, with its built-in PDF viewer), <a href="https://latextools.readthedocs.io/" target="_blank" rel="noreferrer">LaTeXTools</a> for Sublime Text, and <a href="https://www.gnu.org/software/auctex/" target="_blank" rel="noreferrer">AUCTeX</a> (with RefTeX and preview-latex) for Emacs. It describes bbtex v0.1.0; see the <a href="./dev/HANDOFF">handoff</a> for open work.</p><p>&quot;Yes&quot; means a supported workflow in the stock package; many gaps in the other tools can be filled with configuration or engine scripts. The bbtex column is checked against the code and tests. The others come from each project&#39;s documentation, and &quot;Unknown&quot; means I haven&#39;t confirmed it. Corrections are welcome. bbtex relies on TexLab (through BBEdit&#39;s language-server support) for as-you-type completion and adds its own explicit commands on top.</p><h2 id="magic-comments" tabindex="-1">Magic comments <a class="header-anchor" href="#magic-comments" aria-label="Permalink to &quot;Magic comments&quot;">​</a></h2><p>TeXShop started the <code>% !TEX</code> convention; LaTeXTools adopted and extended it. bbtex reads <strong>only <code>root</code> and <code>program</code></strong> (plus TeXShop&#39;s <code>TS-program</code> spelling). Everything else a TeXShop or LaTeXTools document might carry is ignored, and settings like extra options or an output directory go in a <a href="./project-builds#shared-project-settings"><code>.bbtex</code> file</a> instead.</p><table tabindex="0"><thead><tr><th>Comment</th><th>TeXShop</th><th>LaTeXTools</th><th>bbtex</th></tr></thead><tbody><tr><td><code>% !TEX root = …</code></td><td>Yes</td><td>Yes</td><td>Yes, in the first 50 lines, <code>%!TEX</code> or <code>% !TEX</code></td></tr><tr><td><code>% !TEX TS-program = …</code></td><td>Yes</td><td>Yes</td><td>Yes, as an alias of <code>program</code></td></tr><tr><td><code>% !TEX program = …</code></td><td>No</td><td>Yes</td><td>Yes</td></tr><tr><td>TeXShop engine names (<code>pdflatexmk</code>, <code>xelatexmk</code>, …)</td><td>Yes (engine scripts)</td><td>Unknown</td><td>Built-in names map to pdfLaTeX, XeLaTeX, LuaLaTeX; custom engine scripts are not run</td></tr><tr><td><code>% !TEX encoding = …</code></td><td>Yes</td><td>No</td><td>Parsed but not used</td></tr><tr><td><code>% !TEX spellcheck = …</code></td><td>Yes</td><td>Yes</td><td>No</td></tr><tr><td><code>% !TEX parameter = …</code></td><td>Yes</td><td>No</td><td>No</td></tr><tr><td><code>% !BIB TS-program = …</code></td><td>Yes</td><td>No</td><td>No; latexmk picks BibTeX or Biber</td></tr><tr><td><code>% !TEX options = …</code></td><td>No</td><td>Yes</td><td>No; use <code>options =</code> in <code>.bbtex</code></td></tr><tr><td><code>% !TEX output_directory = …</code></td><td>No</td><td>Yes</td><td>No; use <code>output_directory =</code> in <code>.bbtex</code></td></tr><tr><td><code>% !TEX jobname = …</code> / <code>aux_directory</code></td><td>No</td><td>Yes</td><td>No</td></tr><tr><td>Emacs <code>TeX-master</code> / <code>TeX-engine</code></td><td>No</td><td>No</td><td>No (AUCTeX&#39;s own format)</td></tr></tbody></table><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>TeXShop</th><th>LaTeXTools</th><th>AUCTeX</th><th>bbtex</th></tr></thead><tbody><tr><td>One-key build</td><td>⌘T (Typeset)</td><td>⌘B</td><td><code>C-c C-c</code></td><td>⌘K</td></tr><tr><td>latexmk builds</td><td>Via <code>…mk</code> engine scripts</td><td>Yes (default)</td><td>Via add-on or custom command</td><td>Yes</td></tr><tr><td>pdfLaTeX / XeLaTeX / LuaLaTeX</td><td>Yes</td><td>Yes</td><td>Yes (<code>TeX-engine</code>)</td><td>Yes</td></tr><tr><td>Tectonic</td><td>Custom engine script</td><td>No</td><td>Custom command</td><td>Yes, direct pipeline</td></tr><tr><td>BibTeX / Biber</td><td>Separate command, or latexmk engines</td><td>Via latexmk</td><td>Via command chain</td><td>Via latexmk; tested with MacTeX Biber ≥ 2.21</td></tr><tr><td>Named build variants</td><td>Engine menu</td><td>Builder settings</td><td><code>TeX-command-list</code></td><td><code>.bbtex</code> profiles; <strong>Compile With…</strong> (⇧⌘K)</td></tr><tr><td>Save before build</td><td>Current file</td><td>Current file</td><td>Asks</td><td>Saves modified open project inputs</td></tr><tr><td>Cancel a build</td><td>Yes (Abort)</td><td>Yes</td><td>Yes (<code>TeX-kill-job</code>)</td><td>Yes, whole process group</td></tr><tr><td>Clean auxiliary files</td><td>Yes (Trash Aux Files)</td><td>Yes</td><td>Yes (<code>TeX-clean</code>)</td><td><strong>Clean</strong> (keeps PDF) / <strong>Clean All Build Output</strong></td></tr><tr><td>Custom build logic</td><td>Engine shell scripts</td><td>Python builders</td><td>Emacs Lisp</td><td>No; profiles cover engine and options</td></tr></tbody></table><h2 id="project-settings" tabindex="-1">Project settings <a class="header-anchor" href="#project-settings" aria-label="Permalink to &quot;Project settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>TeXShop</th><th>LaTeXTools</th><th>AUCTeX</th><th>bbtex</th></tr></thead><tbody><tr><td>Main file for included files</td><td><code>% !TEX root</code></td><td><code>% !TEX root</code>, project file</td><td><code>TeX-master</code></td><td><code>%!TEX root</code> or <code>root =</code> in <code>.bbtex</code></td></tr><tr><td>Project settings file</td><td>No</td><td><code>.sublime-project</code></td><td><code>.dir-locals.el</code></td><td><code>.bbtex</code> (root, engine, output, options, profiles)</td></tr><tr><td>Guided setup</td><td>No</td><td>No</td><td>Asks for master on first build</td><td><strong>Configure Document…</strong> writes root/program comments</td></tr><tr><td>Global user config</td><td>Preferences</td><td>JSON settings</td><td>Emacs Lisp</td><td>No</td></tr><tr><td>Setup diagnostics</td><td>No</td><td>System check command</td><td>No</td><td><strong>LaTeX — Doctor</strong></td></tr></tbody></table><h2 id="errors-and-logs" tabindex="-1">Errors and logs <a class="header-anchor" href="#errors-and-logs" aria-label="Permalink to &quot;Errors and logs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>TeXShop</th><th>LaTeXTools</th><th>AUCTeX</th><th>bbtex</th></tr></thead><tbody><tr><td>Error list</td><td>Console output</td><td>Output panel</td><td><code>C-c ` </code></td><td>BBEdit results browser</td></tr><tr><td>Jump to the source line</td><td>Unknown</td><td>Yes</td><td>Yes</td><td>Yes, click the entry</td></tr><tr><td>Warnings and bad boxes</td><td>In the log</td><td>Yes (toggle)</td><td>Yes (toggle)</td><td><strong>Show Build Results</strong>, no rebuild</td></tr><tr><td>Full log</td><td>Yes</td><td>Yes</td><td>Yes</td><td><strong>Open Build Log</strong></td></tr><tr><td>79-column line unwrapping</td><td>Unknown</td><td>Partial</td><td>Yes</td><td>Yes</td></tr></tbody></table><h2 id="pdf-viewing-and-synctex" tabindex="-1">PDF viewing and SyncTeX <a class="header-anchor" href="#pdf-viewing-and-synctex" aria-label="Permalink to &quot;PDF viewing and SyncTeX&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>TeXShop</th><th>LaTeXTools</th><th>AUCTeX</th><th>bbtex</th></tr></thead><tbody><tr><td>Viewer</td><td>Built-in (external optional)</td><td>Skim, Preview, others</td><td>Any configured</td><td>Skim</td></tr><tr><td>Forward search</td><td>Yes</td><td>Yes</td><td>Yes (<code>TeX-source-correlate-mode</code>)</td><td>Yes; updates Skim without taking focus</td></tr><tr><td>Inverse search</td><td>Yes (⌘-click)</td><td>Yes</td><td>Yes (Emacs server)</td><td>Yes (⌘-click), after Skim&#39;s sync setting</td></tr></tbody></table><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>TeXShop</th><th>LaTeXTools</th><th>AUCTeX</th><th>bbtex</th></tr></thead><tbody><tr><td>Section list</td><td>Tags menu (current file)</td><td>Yes (project-wide)</td><td>RefTeX <code>C-c =</code></td><td><strong>Project Outline Window</strong>, project-wide, refreshes on save</td></tr><tr><td>Search labels, equations, captions</td><td>Unknown</td><td>Sections and labels</td><td>RefTeX TOC and labels</td><td>Yes, across included files, with <code>kind:</code> filters</td></tr><tr><td>Go to label definition</td><td>No</td><td>Yes</td><td>RefTeX</td><td>TexLab Go to Definition</td></tr><tr><td>Jump to an <code>\\input</code> file</td><td>Unknown</td><td>Yes</td><td>Partial</td><td>No dedicated command</td></tr><tr><td>Stale-target protection</td><td>No</td><td>No</td><td>No</td><td>Jumps refuse changed or unsaved targets</td></tr></tbody></table><h2 id="citations-and-references" tabindex="-1">Citations and references <a class="header-anchor" href="#citations-and-references" aria-label="Permalink to &quot;Citations and references&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>TeXShop</th><th>LaTeXTools</th><th>AUCTeX</th><th>bbtex</th></tr></thead><tbody><tr><td>Citation completion</td><td>Unknown (BibDesk integration)</td><td>Yes</td><td>RefTeX <code>C-c [</code></td><td>TexLab completion</td></tr><tr><td>Citation search picker</td><td>Unknown</td><td>Quick panel</td><td>RefTeX regexp search</td><td><strong>Insert Citation</strong>: key, author, title, year; multiple keys</td></tr><tr><td>Accent- and case-insensitive search</td><td>Unknown</td><td>Unknown</td><td>Partial</td><td>Yes</td></tr><tr><td>Reference picker with context</td><td>Unknown</td><td>Quick panel</td><td>RefTeX label menu</td><td><strong>Insert Reference</strong>: label plus nearby text</td></tr><tr><td>Duplicate-key handling</td><td>Unknown</td><td>Unknown</td><td>Warns</td><td>Refuses ambiguous keys</td></tr></tbody></table><h2 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>TeXShop</th><th>LaTeXTools</th><th>AUCTeX</th><th>bbtex</th></tr></thead><tbody><tr><td>Insert environment</td><td>Macros, command completion</td><td>Snippets</td><td><code>C-c C-e</code></td><td>Clippings</td></tr><tr><td>Change environment</td><td>No</td><td>Yes</td><td><code>C-u C-c C-e</code></td><td><strong>Change Environment</strong>, one undo, nested-aware</td></tr><tr><td>Toggle starred environment</td><td>No</td><td>Yes</td><td>Partial</td><td><strong>Toggle Starred Environment</strong></td></tr><tr><td>Wrap selection</td><td>Macros</td><td>Yes</td><td><code>C-c C-e</code> on region</td><td><strong>Wrap in Environment</strong>; clippings</td></tr><tr><td>Command completion</td><td>Yes (Esc, completion list)</td><td>CWL files</td><td>Style files</td><td>TexLab and BBEdit clippings</td></tr><tr><td>Symbol palettes</td><td>Yes (LaTeX and Matrix panels)</td><td>No</td><td>Math menu</td><td>No</td></tr><tr><td>Folding</td><td>Unknown</td><td>No</td><td><code>TeX-fold-mode</code></td><td>No</td></tr><tr><td>Package documentation</td><td>Yes (texdoc)</td><td>Yes (texdoc)</td><td>Yes (texdoc)</td><td><strong>Package Documentation</strong> (texdoc)</td></tr></tbody></table><h2 id="previews" tabindex="-1">Previews <a class="header-anchor" href="#previews" aria-label="Permalink to &quot;Previews&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>TeXShop</th><th>LaTeXTools</th><th>AUCTeX</th><th>bbtex</th></tr></thead><tbody><tr><td>Equation preview</td><td>Unknown</td><td>Inline phantoms</td><td>Inline images (preview-latex)</td><td>Separate reusable BBEdit window</td></tr><tr><td>Uses the document preamble</td><td>Unknown</td><td>Configurable</td><td>Yes</td><td>Yes, the main file&#39;s saved preamble</td></tr><tr><td>Follows the cursor or selection</td><td>No</td><td>Yes (phantoms update)</td><td>On demand</td><td>Refresh on save or live selection (both opt-in)</td></tr><tr><td>Refresh when a macro file changes</td><td>No</td><td>No</td><td>No</td><td>Yes, for recorded inputs</td></tr><tr><td>Image preview on hover</td><td>No</td><td>Yes</td><td>No</td><td>No</td></tr></tbody></table><h2 id="where-bbtex-is-ahead" tabindex="-1">Where bbtex is ahead <a class="header-anchor" href="#where-bbtex-is-ahead" aria-label="Permalink to &quot;Where bbtex is ahead&quot;">​</a></h2><ol><li><strong>Your editor stays BBEdit.</strong> TeXShop is a good LaTeX editor, but if you already live in BBEdit, bbtex brings builds, SyncTeX and previews to it instead of asking you to switch.</li><li><strong>Project safety.</strong> Builds save the project&#39;s inputs, run one at a time per project, and cancel whole process groups. Outline jumps and picker insertions refuse stale targets instead of landing on the wrong line.</li><li><strong>Project-wide tools.</strong> The outline, pickers and previews follow <code>\\input</code> and <code>\\include</code> across the whole project.</li><li><strong>Tested against real engines.</strong> Builds and log parsing run against pdfLaTeX, XeLaTeX, LuaLaTeX and Tectonic corpora with BibTeX and Biber.</li><li><strong>Standalone CLI and Doctor.</strong> Every feature is a <code>bbtex</code> subcommand, and Doctor checks the setup.</li></ol><h2 id="where-bbtex-is-behind" tabindex="-1">Where bbtex is behind <a class="header-anchor" href="#where-bbtex-is-behind" aria-label="Permalink to &quot;Where bbtex is behind&quot;">​</a></h2><ol><li><strong>Magic comments.</strong> Only <code>root</code> and <code>program</code> are read. TeXShop&#39;s <code>spellcheck</code>, <code>parameter</code> and <code>% !BIB</code>, and LaTeXTools&#39; <code>options</code>, <code>output_directory</code> and <code>jobname</code>, are ignored.</li><li><strong>No built-in viewer.</strong> TeXShop has its own PDF window; bbtex needs Skim.</li><li><strong>Inline previews.</strong> BBEdit has no API for images in the text view, so previews live in a separate window.</li><li><strong>As-you-type help.</strong> Completion depends on TexLab and an explicit Complete command; there are no symbol palettes, math-mode snippets or folding.</li><li><strong>Extensibility.</strong> TeXShop engine scripts, LaTeXTools builders and AUCTeX&#39;s Emacs Lisp let you script your own builds; bbtex has profiles and options.</li><li><strong>Unsaved buffers.</strong> The outline, pickers and previews read saved files.</li></ol><h2 id="candidate-follow-ups" tabindex="-1">Candidate follow-ups <a class="header-anchor" href="#candidate-follow-ups" aria-label="Permalink to &quot;Candidate follow-ups&quot;">​</a></h2><ul><li>Read more of the magic comments TeXShop and LaTeXTools users already have (<code>options</code> and <code>output_directory</code> are the likely ones), mapping them onto the existing <code>.bbtex</code> settings.</li><li>A command to open the file under an <code>\\input</code>/<code>\\include</code> at the cursor.</li><li>Unsaved-buffer snapshots for preview dependencies and the outline.</li></ul><p>Deliberately out of scope: builder plugin APIs, running TeXShop engine scripts, viewers other than Skim, and reimplementing completion that TexLab already provides.</p>',29)])])}const b=e(a,[["render",n]]);export{u as __pageData,b as default};
